'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function pyrepr(value){if(value===null)return 'None';if(value===true)return 'True';if(value===false)return 'False';if(Array.isArray(value))return '['+value.map(pyrepr).join(', ')+']';if(typeof value==='object')return '{'+Object.entries(value).map(([k,v])=>JSON.stringify(k)+': '+pyrepr(v)).join(', ')+'}';return JSON.stringify(value);}
const uiIcons={"home": "<path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z\"/>", "path": "<circle cx=\"6\" cy=\"5\" r=\"2\"/><circle cx=\"18\" cy=\"19\" r=\"2\"/><path d=\"M8 5h8a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h8\"/>", "projects": "<rect x=\"3\" y=\"7\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M8 7V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v3M3 12h18M10 12v3h4v-3\"/>", "review": "<path d=\"M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2\"/>", "journal": "<path d=\"M5 3h13a1 1 0 0 1 1 1v17H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2ZM3 17h16M8 7h7M8 11h5\"/>", "settings": "<path d=\"m10 3-.6 2.3-2 .9-2.1-.7-2 3.5L5 10.6v2.2l-1.7 1.6 2 3.5 2.1-.7 2 .9L10 21h4l.6-2.9 2-.9 2.1.7 2-3.5-1.7-1.6v-2.2l1.7-1.6-2-3.5-2.1.7-2-.9L14 3Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>", "game": "<rect x=\"2\" y=\"7\" width=\"20\" height=\"12\" rx=\"4\"/><path d=\"M7 10v6M4 13h6M16 11h.01M19 15h.01M9 7V4h6\"/>", "chart": "<path d=\"M4 3v18h17M8 16v-4M13 16V7M18 16V4\"/>", "library": "<rect x=\"3\" y=\"4\" width=\"5\" height=\"17\" rx=\"1\"/><rect x=\"9\" y=\"4\" width=\"5\" height=\"17\" rx=\"1\"/><path d=\"m15 5 4-1 4 16-4 1ZM5 8h1M11 8h1\"/>", "code": "<path d=\"m8 5-6 7 6 7m8-14 6 7-6 7M14 3l-4 18\"/>"};
function icon(name){return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(uiIcons[name]||uiIcons.code)+'</svg>';}
const KEY='forge-progress-v1',RECOVERY_PREFIX=KEY+'-recovery-',SNAPSHOT_KEY='forge-snapshots-v1',LAST_EXPORT_KEY='forge-last-export',BACKUP_SNOOZE_KEY='forge-backup-snooze',TAB_KEY='forge-tab-signal';
const SNAPSHOT_LIMIT=5,HOUR=3600000,DAY=24*HOUR,SNAPSHOT_SPACING=6*HOUR,BACKUP_REMINDER_AFTER=7*DAY,BACKUP_SNOOZE=3*DAY;
const emptyState=()=>({version:1,completed:{},drafts:{},notes:{},assisted:{},hints:{},explanations:{},ratings:{},scratch:'',projectChecks:{},labChecks:{},labNotes:{},evidence:{},reviews:{},events:[],timerMinutes:45});
let state=emptyState(), curriculum, handbook, lessons=[], weeks=[], current=null, worker=null, runTimeout, passedCode=null, rating=null, lastRun=null, elapsed=0, clock=null, timerRunning=false, saveFailed=false, saveBlocked=false, progressUnreadable=false, lastSnapshotAt=0;
function recoveryKeys(){const keys=[];try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith(RECOVERY_PREFIX))keys.push(key);}}catch{}return keys.sort();}
/* A record that cannot be read is copied aside first, so the next save can never destroy it. If the copy fails, saving stops and the record stays where it is. */
function savedProgressShapeOK(value){
  const record=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),finite=v=>typeof v==='number'&&Number.isFinite(v);
  if(!record(value)||value.version!==1)return false;
  const strings=['drafts','notes','explanations','labNotes','evidence'],booleans=['assisted','projectChecks','labChecks'];
  for(const key of [...strings,...booleans,'completed','reviews','hints','ratings']){
    if(!(key in value))continue; // Old saves may omit fields added in later editions.
    if(!record(value[key]))return false;
    for(const item of Object.values(value[key])){
      if(strings.includes(key)&&typeof item!=='string')return false;
      if(booleans.includes(key)&&typeof item!=='boolean')return false;
      if(['completed','reviews'].includes(key)){
        if(!record(item))return false;
        for(const field of ['at','due'])if(field in item&&!finite(item[field]))return false;
        if(key==='completed'&&'assisted' in item&&typeof item.assisted!=='boolean')return false;
        if(key==='reviews'&&'stage' in item&&(!Number.isInteger(item.stage)||item.stage<0||item.stage>3))return false;
      }
      if(key==='hints'&&(!Number.isInteger(item)||item<0||item>2))return false;
      if(key==='ratings'&&![1,2,3].includes(item))return false;
    }
  }
  if('scratch' in value&&typeof value.scratch!=='string')return false;
  if('timerMinutes' in value&&(!finite(value.timerMinutes)||value.timerMinutes<=0))return false;
  if('events' in value&&(!Array.isArray(value.events)||value.events.some(e=>!record(e)||!Number.isInteger(e.id)||e.id<1||!finite(e.at))))return false;
  if('game' in value){
    const g=value.game;if(!record(g))return false;
    if('workspace' in g&&(!record(g.workspace)||typeof g.workspace.repoUrl!=='string'||!record(g.workspace.checks)||Object.values(g.workspace.checks).some(v=>typeof v!=='boolean')))return false;
    if('labCommits' in g&&(!record(g.labCommits)||Object.values(g.labCommits).some(v=>!record(v)||typeof v.sha!=='string'||typeof v.pushed!=='boolean')))return false;
    if('legacyLabs' in g&&(!record(g.legacyLabs)||Object.values(g.legacyLabs).some(v=>typeof v!=='boolean')))return false;
    for(const key of ['awards','bounties','attempts','traces','revealed','briefs','qbriefs']){
      if(!(key in g))continue;
      if(!record(g[key]))return false;
      for(const item of Object.values(g[key])){
        if(['revealed','briefs','qbriefs'].includes(key)){if(typeof item!=='boolean')return false;continue;}
        if(!record(item))return false;
        if(key==='awards'&&(!finite(item.xp)||item.xp<0))return false;
        if(key==='bounties'&&(!finite(item.due)||!finite(item.created)))return false;
        if(key==='attempts'&&(('fails' in item&&!finite(item.fails))||('diag' in item&&!Array.isArray(item.diag))))return false;
      }
    }
    if('tests' in g){
      if(!record(g.tests)||('history' in g.tests&&!Array.isArray(g.tests.history)))return false;
      if(g.tests.history?.some(h=>!record(h)||!Array.isArray(h.problems)||h.problems.some(p=>!record(p))))return false;
      const active=g.tests.active;
      if(active!=null&&(!record(active)||!finite(active.startedAt)||!Array.isArray(active.problems)||active.problems.length!==3||!active.problems.every(id=>Number.isInteger(id)&&id>0)||!record(active.code)||!record(active.results)))return false;
    }
  }
  return true;
}
function readSavedProgress(){let raw=null;try{raw=localStorage.getItem(KEY);}catch{return;}if(raw===null)return;let old=null;try{old=JSON.parse(raw);}catch{}if(savedProgressShapeOK(old)){state={...emptyState(),...old};return;}progressUnreadable=true;try{if(!recoveryKeys().some(key=>localStorage.getItem(key)===raw))localStorage.setItem(RECOVERY_PREFIX+Date.now(),raw);}catch{saveBlocked=true;}}
readSavedProgress();
/* The main record always wins storage space: snapshots are dropped, oldest first, to make room for it. */
function writeProgress(){const raw=JSON.stringify(state);try{localStorage.setItem(KEY,raw);}catch(error){const original=readSnapshots(),list=[...original];while(list.length){list.shift();writeSnapshots([...list]);try{localStorage.setItem(KEY,raw);return;}catch{}}writeSnapshots(original);throw error;}}
function save(){if(saveBlocked)return;try{writeProgress();if(saveFailed){saveFailed=false;toast('Saving is working again.');}takeSnapshot();}catch{if(!saveFailed){saveFailed=true;toast('Browser storage is unavailable. Export a backup to keep your work.');}}}
function readSnapshots(){try{const list=JSON.parse(localStorage.getItem(SNAPSHOT_KEY));return Array.isArray(list)?list.filter(s=>s&&Number.isFinite(s.at)&&s.state&&typeof s.state==='object'):[];}catch{return [];}}
function writeSnapshots(list){while(list.length){try{localStorage.setItem(SNAPSHOT_KEY,JSON.stringify(list));return true;}catch{list.shift();}}try{localStorage.removeItem(SNAPSHOT_KEY);}catch{}return false;}
function hasProgress(){return Object.keys(state.completed).length+Object.keys(state.drafts).length>0;}
function takeSnapshot(force=false){const now=Date.now();if(saveBlocked||!hasProgress()||(!force&&now-lastSnapshotAt<SNAPSHOT_SPACING))return;lastSnapshotAt=now;const list=readSnapshots(),raw=JSON.stringify(state),latest=list[list.length-1];if(latest&&JSON.stringify(latest.state)===raw)return;writeSnapshots([...list,{at:now,state:JSON.parse(raw)}].slice(-SNAPSHOT_LIMIT));}
function restoreSnapshot(at){const snapshot=readSnapshots().find(s=>s.at===at);if(!snapshot)return toast('That snapshot is no longer available.');const raw=JSON.stringify(snapshot.state);return importBackup({size:raw.length,text:async()=>raw});}
/* Persistent banners above the page, for anything that should not vanish like a toast. */
const notices=new Map();
function renderNotices(){const bar=$('#notices');if(bar)bar.innerHTML=[...notices].map(([id,n])=>`<div class="notice ${n.tone}" role="${n.tone==='warn'?'alert':'status'}"><p>${esc(n.text)}</p><div class="notice-actions">${n.actions||''}<button class="notice-dismiss" data-notice-dismiss="${id}">Dismiss</button></div></div>`).join('');}
function showNotice(id,tone,text,actions=''){notices.set(id,{tone,text,actions});renderNotices();}
function clearNotice(id){if(notices.delete(id))renderNotices();}
function showRecoveryNotice(){if(progressUnreadable)showNotice('recovery','warn',saveBlocked?'Your saved progress could not be read, and there was no room to copy it aside. Saving is paused so nothing gets overwritten. Open settings to download the damaged data or restore a snapshot.':'Your saved progress could not be read, so Forge started empty. Nothing was lost: the damaged data was copied aside. Open settings to restore a snapshot or download that copy.','<a class="btn small" href="#settings">Open settings</a>');}
function lastExportTime(){try{return Number(localStorage.getItem(LAST_EXPORT_KEY))||0;}catch{return 0;}}
function lastBackupText(){const last=lastExportTime();return last?'Last backup from this browser: '+new Date(last).toLocaleString():'No backup exported from this browser yet.';}
function checkBackupReminder(){if(!hasProgress())return;const now=Date.now(),last=lastExportTime(),since=last||Math.min(now,...state.events.map(e=>e.at));let snoozed=0;try{snoozed=Number(localStorage.getItem(BACKUP_SNOOZE_KEY))||0;}catch{}if(now-since<=BACKUP_REMINDER_AFTER||now<snoozed)return;const days=Math.floor((now-since)/DAY);showNotice('backup','gentle',(last?`It has been ${days} days since your last backup.`:`You have ${days} days of progress and no backup yet.`)+' Exporting takes a few seconds and keeps your work safe if this browser’s data is cleared.','<button class="btn small" data-action="export">Export backup ↓</button>');}
function exportBackup(){download('forge-progress-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');try{localStorage.setItem(LAST_EXPORT_KEY,String(Date.now()));}catch{}clearNotice('backup');if($('#last-backup'))$('#last-backup').textContent=lastBackupText();}
function dismissNotice(id){if(id==='backup'){try{localStorage.setItem(BACKUP_SNOOZE_KEY,String(Date.now()+BACKUP_SNOOZE));}catch{}}clearNotice(id);}
/* Two tabs each hold their own copy of state, and the last save wins. Tabs announce themselves through localStorage, which fires a storage event in every other tab. A closing tab stops answering, or the recount it triggers would report it as still open. */
let tabLeaving=false;
function signalTabs(type){try{localStorage.setItem(TAB_KEY,`${type}:${Date.now()}:${Math.random()}`);}catch{}}
function warnOtherTab(){if(!notices.has('stale'))showNotice('tabs','warn','Forge is open in another tab. Each tab saves its own copy, so use one at a time to avoid overwriting your work.');}
function handleStorageEvent(e){if(tabLeaving)return;if(e.key===KEY&&e.newValue!==null){clearNotice('tabs');showNotice('stale','warn','Another tab just saved newer progress. Reload this tab before you continue, or saving here could overwrite that work.','<button class="btn small" data-safety="reload">Reload this tab</button>');}if(e.key===TAB_KEY&&e.newValue){const [type]=e.newValue.split(':');if(type==='ping'){warnOtherTab();signalTabs('here');}if(type==='here')warnOtherTab();if(type==='bye'){clearNotice('tabs');signalTabs('ping');}}}
window.addEventListener('storage',handleStorageEvent);
window.addEventListener('pagehide',()=>{tabLeaving=true;signalTabs('bye');});
window.addEventListener('pageshow',e=>{if(e.persisted){tabLeaving=false;signalTabs('ping');}});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function download(name,body,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function weekStart(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.getTime();}
function weeklyEvents(){return state.events.filter(e=>e.at>=weekStart());}
const isCore=l=>!l.track;
function coreLessons(){return lessons.filter(isCore);}
function nextLesson(){return lessons.find(l=>isCore(l)&&!state.completed[l.id])||coreLessons().at(-1);}
function nextHashAfter(l){const n=lessons[l.id];if(!l.track&&(!n||n.week!==l.week)&&typeof labDone==='function'&&!labDone(l.week))return '#lab/'+l.week;if(l.track)return n&&n.chapter===l.chapter?'#lesson/'+n.id:'#quests/'+l.chapter;return n&&isCore(n)?'#lesson/'+n.id:'#projects';}
function countCompleted(){return coreLessons().filter(l=>state.completed[l.id]).length;}
function independent(){return Object.values(state.completed).filter(c=>!c.assisted).length;}
function dueLessons(){return lessons.filter(l=>{const c=state.completed[l.id];return c&&((state.reviews[l.id]?.due||c.due||Infinity)<=Date.now());});}
function updateNav(page){const hud=$('#quest-hud');if(hud)hud.hidden=page!=='quests'&&page!=='test';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const n=Math.min(4,weeklyEvents().length);$('#side-dots').innerHTML=[0,1,2,3].map(i=>`<i class="${i<n?'done':''}"></i>`).join('');$('#breadcrumb').textContent=({home:'Your workspace',path:'Learning path',projects:'Project workshop',review:'Skill review',journal:'Your notebook',settings:'Preferences & backup',lesson:'Practice quest',quests:'Quest book',practice:'Optional practice'})[page]||'Your workspace';}
function header(title,sub,right=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${right}</div>`;}
function progressForWeek(w){return lessons.filter(l=>isCore(l)&&l.week===w&&state.completed[l.id]).length;}
const projects=[{title:'Tiny dungeon engine',icon:'game',id:16,week:4,desc:'Build the core of a grid-based game. Turn commands into movement, then add a world of your own.',checks:['Movement engine passes its checks','Add walls, treasure, and a replay loop in VS Code','Write a README and three extra tests']},{title:'Playtime report',icon:'chart',id:24,week:6,desc:'Turn a small game-session dataset into a useful report with totals and a CSV export.',checks:['Aggregation function passes its checks','Read a local JSON file and export CSV','Handle invalid records and document the format']},{title:'Game-library organizer',icon:'library',id:44,week:11,desc:'Combine your automation skills into a tool that imports, cleans, searches, and exports your game library.',checks:['Complete weeks 6–11 core functions','Connect them into a working CLI in VS Code','Ship sample data, tests, and setup instructions']},{title:'Your independent build',icon:'code',id:48,week:12,desc:'Choose a small problem you care about. Define what done means, build a working version, and explain your choices.',checks:['Write inputs, outputs, and acceptance examples','Implement and debug without generated solutions','Publish a README and demonstrate the working program']}];
function renderReview(){const due=dueLessons(),finished=lessons.filter(l=>state.completed[l.id]);return `${header('Make it stick','Come back to a skill. Start from a blank page. See what you remember.')}<div class="path-intro"><strong>${due.length} ready</strong><p>Reviews are scheduled 1, 3, 7, then 14 days after successful attempts. A review starts with a fresh editor. Try without hints; if you need help, we’ll revisit it tomorrow. Repeated tasks are recall practice, not proof of general mastery.</p></div>${due.length?due.map(reviewRow).join(''):`<div class="card empty-state"><span style="font-size:30px;color:#8ca773">↻︎</span><h3>${finished.length?'You’re up to date.':'Your first review starts with a small win.'}</h3><p>${finished.length?'Nothing is due today. You can still revisit a completed session below.':'Complete a session and it will appear here when it is time to revisit it. Your notes and previous attempts stay saved.'}</p><a class="btn" href="#lesson/${nextLesson().id}">Continue learning →</a></div>`}${finished.length?`<div class="section-title" style="margin-top:27px"><h2>Revisit any completed skill</h2><span class="muted" style="font-size:10px">${finished.length} sessions</span></div>${finished.filter(l=>!due.includes(l)).map(reviewRow).join('')}`:''}`;}
function reviewRow(l){const c=state.completed[l.id],due=state.reviews[l.id]?.due||c.due;return `<div class="card review-row"><div><span class="badge">${c.assisted?'GUIDED PRACTICE':'INDEPENDENT COMPLETION'}</span><h3 style="margin-top:8px">${esc(l.title)}</h3><p>Week ${l.week} · ${due<=Date.now()?'Ready to revisit':'Next review '+new Date(due).toLocaleDateString()} · Start fresh and explain your solution.</p></div><a class="btn light" href="#lesson/${l.id}/review">Try from scratch ↗︎</a></div>`;}
function renderJournal(){const entries=lessons.filter(l=>state.explanations[l.id]||state.notes[l.id]);return `${header('Your notebook','A record of what you built, what broke, and what you figured out.')}<div class="notebook-layout"><div class="card notebook-card"><h3>A place to think</h3><p class="muted" style="font-size:11px;margin-top:6px">Plan a solution. Trace an input. Write down the bug before you fix it.</p><textarea id="scratch" class="form-input" placeholder="What am I trying to build?\nWhat are the inputs and outputs?\nWhat is the smallest example?">${esc(state.scratch)}</textarea><small class="muted" style="font-size:10px">Saved automatically in this browser.</small><details class="reference"><summary>Python pocket reference</summary><pre>${esc('def total(values):\n    result = 0\n    for value in values:\n        result += value\n    return result\n\n# Collections\nitems.append(value)\ncounts[key] = counts.get(key, 0) + 1\nseen = set()\nordered = sorted(items, key=lambda x: x["score"])\n\n# Strings and errors\ntext.strip().lower()\ntry:\n    value = int(text)\nexcept ValueError:\n    value = None\n\n# Debugging questions\n# What did I expect? What happened?\n# What is the smallest failing input?\n# Does the boundary case work?')}</pre></details><a href="#settings" class="btn light small" style="margin-top:18px">Back up your work →</a></div><div><div class="section-title"><h2>Your learning log</h2><button class="btn light small" data-action="export-notes">Export notes</button></div><div class="card notebook-card">${entries.length?entries.slice().reverse().map(l=>`<article class="journal-entry"><a href="#lesson/${l.id}"><h4>${esc(l.title)} ↗︎</h4></a><small>WEEK ${l.week} · ${state.completed[l.id]?(state.completed[l.id].assisted?'Guided practice':'Independent completion'):'In progress'}</small>${state.explanations[l.id]?`<p>${esc(state.explanations[l.id])}</p>`:''}${state.notes[l.id]?`<p><strong>Notes:</strong> ${esc(state.notes[l.id])}</p>`:''}</article>`).join(''):'<p class="muted" style="font-size:12px">Your explanations and session notes will appear here. Start with one small win.</p>'}</div></div></div>`;}
function renderSafetyNet(){const snapshots=readSnapshots().reverse(),recovered=recoveryKeys().concat(saveBlocked?[KEY]:[]);return `<div class="card settings-card"><h3>Automatic snapshots</h3><p>Forge keeps your last ${SNAPSHOT_LIMIT} snapshots in this browser, at most one every 6 hours. They undo mistakes and damaged saves. They live in the same browser storage as your progress, so they do not replace exported backups.</p>${snapshots.length?`<ul class="snapshot-list">${snapshots.map(s=>`<li><span><strong>${esc(new Date(s.at).toLocaleString())}</strong><small>${Object.keys(s.state.completed||{}).length} completed · ${Object.keys(s.state.drafts||{}).length} drafts</small></span><button class="btn light small" data-safety="restore-snapshot" data-snapshot="${s.at}">Restore</button></li>`).join('')}</ul>`:'<p style="margin-bottom:0">No snapshots yet. The first one is saved once you have some progress.</p>'}</div>${recovered.length?`<div class="card settings-card"><h3>Damaged data kept for recovery</h3><p>Forge could not read these saved records, so it kept them unchanged. Download one to keep it safe or to ask for help repairing it.</p><ul class="snapshot-list">${recovered.map(key=>{const at=Number(key.slice(RECOVERY_PREFIX.length));return `<li><span><strong>${esc(Number.isFinite(at)&&at?new Date(at).toLocaleString():'Current saved record')}</strong></span><div class="button-row"><button class="btn light small" data-safety="download-recovery" data-recovery-key="${esc(key)}">Download</button>${key===KEY?'':`<button class="btn light small" data-safety="delete-recovery" data-recovery-key="${esc(key)}">Delete</button>`}</div></li>`;}).join('')}</ul></div>`:''}`;}
function renderSettings(){return `${header('Make this your workspace','A comfortable pace, with your work under your control.')}${appearanceSettings()}<div class="card settings-card"><h3>Your practice rhythm</h3><p>Four sessions a week, whenever they fit. The timer is optional; finishing a task matters more than filling time.</p><label for="timer-minutes" style="font-size:12px">Session timer &nbsp;</label><select id="timer-minutes" class="form-input" style="width:auto"><option value="45" ${state.timerMinutes===45?'selected':''}>45 minutes</option><option value="60" ${state.timerMinutes===60?'selected':''}>60 minutes</option><option value="25" ${state.timerMinutes===25?'selected':''}>25 minutes · lighter day</option></select></div><div class="card settings-card"><h3>Your progress, backed up</h3><p>Progress, code, and notes are saved in this browser on this device. They do not sync automatically. Export a backup before switching devices or clearing browser data; import it here to continue. Import replaces this browser’s progress after confirmation.</p><div class="button-row"><button class="btn" data-action="export">Export backup ↓</button><button class="btn light" data-action="import">Import backup ↑</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p id="last-backup" style="margin-bottom:0">${esc(lastBackupText())}</p><p id="backup-message" aria-live="polite" style="margin-bottom:0"></p></div>${renderSafetyNet()}<div class="card settings-card"><h3>How to use Forge</h3><p>Attempt each problem before opening a hint. Run the checks, inspect failures, then explain your approach. Completions record whether you used hints or a reference solution. Reviews start fresh; self-report outside help honestly. You can skip basics from the learning path if you already know them.</p><p>Python runs locally in a browser worker, with an 8-second limit per execution after the engine loads. The first run downloads the bundled Python engine and may take a moment. Use return for challenge answers and print for your own debugging. Interactive input() and desktop graphics are not supported here. Download your code for full projects in VS Code.</p><p>The 24-week path builds foundations and habits. Confidence comes from independent practice on unfamiliar tasks and finished projects; completing the path is a starting point for that work.</p></div><a href="#home" class="btn light mobile-only">Back to workspace</a>`;}
function renderLesson(l,isReview){const code=isReview?l.starter:(state.drafts[l.id]??l.starter);current={...l,isReview,assisted:isReview?false:!!state.assisted[l.id],hints:isReview?0:(state.hints[l.id]||0),code};passedCode=null;lastRun=null;rating=null;elapsed=0;const practiceFirst=isReview||!!state.completed[l.id]||(state.drafts[l.id]!=null&&state.drafts[l.id]!==l.starter);return `<div class="learn-header"><a class="back" href="${isReview?'#review':l.track?'#quests/'+l.chapter:'#path/week-'+l.week}">← ${isReview?'Skill review':l.track?'Quest book':'Learning path'}</a><div class="timer"><span>◷︎</span><strong id="timer-label">${state.timerMinutes}:00</strong><button data-action="timer" id="timer-toggle">Start focus timer</button><button data-action="timer-reset" aria-label="Reset focus timer">↻︎</button></div></div>${isReview?courseLessonBanner(l,isReview):''}<div class="lesson-title"><span class="badge ${l.checkpoint||l.track?'orange':''}">${l.track?esc(l.phase.toUpperCase())+' · QUEST '+l.session:'WEEK '+String(l.week).padStart(2,'0')+' · SESSION '+l.session} ${isReview?'· REVIEW':''}</span><h1>${esc(l.title)}</h1><p>${isReview?'Rebuild from memory. Your original code is saved; this review uses a separate fresh attempt.':l.checkpoint?'Plan first. Build from the specification. Explain why your solution works.':'Trace the example. Make a plan. Write your own solution.'}</p></div>${isReview?'':lessonTabs(practiceFirst)+lessonLearnView(l,practiceFirst)}<div class="learning-layout practice-view" ${!isReview&&!practiceFirst?'hidden':''}><section class="card lesson-copy"><div class="lstep"><span class="lstep-k"><b>1</b>Your challenge</span><p${l.program?' class="pre-task"':''}>${esc(l.task)}</p><div class="io-example">${l.samplePreview||l.sqlPreview?esc(l.samplePreview||l.sqlPreview).replaceAll('\n','<br>'):l.cases.slice(0,2).map(c=>`${esc(l.name)}(${esc(c.args.map(pyrepr).join(', '))})<br>→ ${esc(pyrepr(c.expected))}`).join('<br><br>')}</div></div><div class="lstep"><span class="lstep-k"><b>2</b>${isReview?'Recall it':'Key idea'}</span>${isReview?`<p>Try the task from memory before revealing the refresher. It’s fine to need help; we’ll schedule another review.</p><button class="btn light small" data-q="refresher" style="margin-top:12px">Reveal refresher · counts as help</button><div id="refresher" hidden><p>${esc(l.concept)}</p>${l.example?`<pre>${esc(l.example)}</pre>`:''}</div>`:`<p>${esc(l.concept)}</p><button class="link-btn" data-ltab="learn">← Reread the lesson</button>`}</div><details class="lstep help-details"><summary>Need a hint?</summary><div class="hint-box" id="hint-box"></div><div class="help-ladder" id="help-ladder"></div><p style="font-size:10px;margin-top:10px" id="assistance-status">${current.assisted?'This attempt uses guidance. Revisit later from scratch.':'Try for 5–10 minutes before reaching for a hint.'}</p></details><details class="lstep lstep-more"><summary><span class="lstep-k"><b>4</b>More: goals, notes, references</span></summary>${isReview?'':`<h3>Goals for this session</h3><ul class="lstep-goals">${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}<h3>Your notes and plan</h3><textarea id="session-note" class="form-input" rows="5" placeholder="Inputs → outputs\nMy plan\nSmallest failing example">${esc(state.notes[l.id]||'')}</textarea>${l.resources?.length?`<h3>References</h3>${sourceLinks(l.resources)}`:''}<div class="extend"><strong>Take it further ↗︎</strong><br>${esc(l.extension)}</div></details></section><div class="editor-column"><section class="editor-panel"><div class="editor-toolbar"><span class="file-name">◉ &nbsp; ${esc(l.file||l.name+'.py')}</span><div><button data-action="download-code">↓ Download</button><button data-action="reset-code">Reset code</button></div></div><div class="editor-wrap"><div class="line-numbers" id="line-numbers" aria-hidden="true"></div><textarea id="editor" aria-label="Python code editor" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off">${esc(code)}</textarea></div><div class="editor-actions"><small id="editor-saved">${isReview?'Fresh review attempt':'Changes saved automatically'}</small><div><button class="btn small" data-action="stop" id="stop-btn" hidden>Stop</button><button class="btn" data-action="run" id="run-btn">▶︎ &nbsp; Run checks</button></div></div></section><section class="card console"><div class="console-heading"><strong>OUTPUT & CHECKS</strong><span class="badge" id="run-status">READY WHEN YOU ARE</span></div>${typeof predictionPanel==='function'?'<details class="prediction-details"><summary>Optional: predict before running</summary>'+predictionPanel(l)+'</details>':''}<div id="test-results"></div><pre id="output">Your code runs in real Python.\nWrite a solution, then run the checks.\nTip: Ctrl/⌘ + Enter runs your code.</pre></section><section class="card completion"><h3>Make the win yours.</h3><p>Pass the checks, then explain the approach in your own words. What would happen on an empty input or a boundary value?</p><label for="explanation">My approach, and one edge case</label><textarea id="explanation" placeholder="I start by… This works because… One edge case is…">${esc(isReview?'':state.explanations[l.id]||'')}</textarea><label>How independently could you do this again?</label><div class="rating-group"><button data-rating="1">Need another try</button><button data-rating="2">With a nudge</button><button data-rating="3">On my own</button></div><label style="margin-bottom:15px"><input type="checkbox" id="outside-help"> I used outside help (AI, someone else, or code from the web). I will revisit this later without the answer.</label><button class="btn" data-action="complete" id="complete-btn">Save session & continue →</button><p id="completion-message" role="status" style="margin-top:10px">Run checks on your current code before completing.</p></section></div></div>`;}
function syncLines(){if($('#editor'))$('#line-numbers').textContent=Array.from({length:$('#editor').value.split('\n').length},(_,i)=>i+1).join('\n');}
function stopRun(message){if(worker){worker.terminate();worker=null;}clearTimeout(runTimeout);if($('#run-btn')){$('#run-btn').disabled=false;$('#run-btn').textContent='▶︎  Run checks';$('#stop-btn').hidden=true;}if(message&&$('#output')){$('#output').textContent=message;$('#run-status').textContent='STOPPED';}}
function markAssisted(){current.assisted=true;if(!current.isReview){state.assisted[current.id]=true;state.hints[current.id]=current.hints;save();}if($('#outside-help'))$('#outside-help').checked=true;$('#assistance-status').textContent='This attempt uses guidance. Revisit later from scratch.';}
function renderHints(){const lesson=lessons[current.id-1];$('#hint-box').innerHTML=lesson.hints.slice(0,Math.min(current.hints,2)).map((h,i)=>`<p><strong>Hint ${i+1}.</strong> ${esc(h)}</p>`).join('');$('#hint-btn').textContent=current.hints>=2?'Hints revealed':'A small hint';}
async function run(){if(!current||$('#run-btn').disabled)return;const l=current,code=$('#editor').value,prediction=typeof questSnapshot==='function'?questSnapshot():null;passedCode=null;if(typeof updateQuestCompletion==='function')updateQuestCompletion();$('#test-results').innerHTML='';$('#output').textContent='Loading Python… First load can take a moment.';$('#run-status').textContent='STARTING PYTHON';$('#run-btn').disabled=true;$('#run-btn').textContent='Running…';$('#stop-btn').hidden=false;worker=new Worker('runner.js?v='+FORGE_VERSION);runTimeout=setTimeout(()=>{stopRun('Python took too long to load. Check your connection and try again.');},90000);worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(runTimeout);$('#run-status').textContent='RUNNING';$('#output').textContent='Checking your function…';runTimeout=setTimeout(()=>stopRun(l.program?'Stopped: this run took too long. Check for a loop that never ends.':'Stopped after 8 seconds. Check for a loop that never ends, or reduce the amount of work.'),l.program?60000:8000);return;}if(data.type==='error'){stopRun('Could not start Python. Please try again.\n'+data.message);return;}if(data.type==='result'){stopRun();const result=data.data;lastRun=result;$('#test-results').innerHTML=l.program&&typeof programResults==='function'?programResults(result):result.results.map((r,i)=>`<div class="test-row ${r.ok?'pass':'fail'}">${r.ok?'✓︎':'×'} Check ${i+1} ${r.ok?'passed':r.mutated&&l.noMutation?'failed: the input was changed, but this task requires it to stay unchanged.':r.error?'<br>'+esc(l.sql?r.error.trim().split('\n').pop().replace(/^sqlite3\.\w+Error: /,'SQL error: '):r.error):`<br>${l.sql?(i?'Dataset: second, hidden data':'Dataset: practice data'):'Input: '+esc(r.args)}<br>Expected: ${esc(r.expected)}<br>Received: ${esc(r.actual)}`}</div>`).join('');const ok=!result.error&&result.results.length===l.cases.length&&result.results.every(r=>r.ok);if(ok&&$('#editor').value===code)passedCode=code;$('#run-status').textContent=ok?'ALL CHECKS PASSED':'LET’S DEBUG';$('#output').textContent=(result.error||'')+(result.stdout?'\nYour output:\n'+result.stdout:'')+(ok?'\nAll checks passed. Explain your approach below.':!result.error?'\nTrace the smallest failing example and try again.':'\nRead the last line of the error first.');$('#completion-message').textContent=ok?'Checks passed. Add an explanation and choose your independence level.':'Keep going. Complete the session after the current code passes.';if(typeof questAfterRun==='function')questAfterRun(result,ok,code,prediction);if(typeof updateQuestCompletion==='function')updateQuestCompletion();}};worker.onerror=e=>stopRun('Python could not run. Please retry. '+e.message);worker.postMessage({code:l.sql&&typeof sqlWrap==='function'?sqlWrap(l,code):code,cases:l.cases,name:l.name,packages:l.packages||[],checkMutation:!!l.noMutation,requirements:l.requirements||[],program:!!l.program});}
function complete(){const explanation=$('#explanation').value.trim(),code=$('#editor').value;if(passedCode!==code)return toast('Run the checks on your current code and pass them first.');if(explanation.length<30)return toast('Add an explanation of at least 30 characters, including an edge case.');if(!rating)return toast('Choose how independently you could do this again.');const helped=current.assisted||$('#outside-help').checked||rating<3;const reward=typeof questOnComplete==='function'?questOnComplete(helped):'';const previous=state.completed[current.id],review=state.reviews[current.id],stage=helped?0:Math.min(3,(review?.stage??-1)+1);const due=Date.now()+[1,3,7,14][stage]*86400000;state.explanations[current.id]=explanation;state.ratings[current.id]=rating;state.reviews[current.id]={stage,due};state.completed[current.id]={at:Date.now(),assisted:previous?(previous.assisted && helped):helped,due,confidence:rating};if(!current.isReview)state.drafts[current.id]=code;if(!previous||current.isReview)state.events.push({id:current.id,at:Date.now(),review:current.isReview,assisted:helped});save();toast(reward||(helped?'Practice saved. Revisit this skill tomorrow.':'Independent completion saved. Nice work.'));location.hash=(typeof questReturnHash==='function'&&questReturnHash())||(current.isReview?'#review':nextHashAfter(current));}
function tick(){const remain=Math.max(0,state.timerMinutes*60-elapsed);if($('#timer-label'))$('#timer-label').textContent=`${Math.floor(Math.ceil(remain)/60)}:${String(Math.ceil(remain)%60).padStart(2,'0')}`;if(remain===0){pauseTimer();toast('Focus session complete. Take a break or finish your thought.');}}
let lastTick=0;
function pauseTimer(){clearInterval(clock);clock=null;timerRunning=false;if($('#timer-toggle'))$('#timer-toggle').textContent='Resume timer';}
function route(){stopRun();pauseTimer();const [page='home',id,mode]=location.hash.slice(1).split('/');const main=$('#main');if(!lessons.length)return;current=null;if(page==='lesson'){const l=lessons.find(x=>x.id===Number(id));if(!l){location.hash='#path';return;}main.innerHTML=renderLesson(l,mode==='review');syncLines();renderHints();}else{const renders={home:renderHome,path:renderPath,projects:renderProjects,review:renderReview,journal:renderJournal,settings:renderSettings,guide:renderGuide,setup:()=>renderSetup(Number(id)||1,Number(mode)||1),workspace:()=>renderWorkspace(Number(id)||1,Number(mode)||1),practice:()=>typeof renderPracticeLibrary==='function'?renderPracticeLibrary():renderPath(),lab:()=>renderLab(Number(id)||1),resources:renderResources,readiness:renderReadiness,unit:()=>renderUnit(Number(id)||1),quests:()=>typeof renderQuests==='function'?renderQuests(id):renderPath(),test:()=>typeof renderTest==='function'?renderTest(id):renderPath()};main.innerHTML=(renders[page]||renderHome)();}updateNav(["unit","guide","resources","setup"].includes(page)?"path":["readiness","lab"].includes(page)?"projects":["test","practice"].includes(page)?"quests":page);if(["unit","guide","resources","readiness","test","setup","lab","workspace"].includes(page))$("#breadcrumb").textContent=({unit:"Weekly handbook",guide:"Start here",setup:"Lab setup",workspace:"GitHub workspace",lab:"Independent lab",resources:"Source library",readiness:"Readiness evidence",test:"Timed test"})[page];window.scrollTo(0,0);if(typeof questMounted==='function')questMounted(page,id,mode);if(typeof journeyMounted==='function')journeyMounted(page,id,mode);}
document.addEventListener('input',e=>{if(e.target.id==='editor'){current.code=e.target.value;if(current.testRun){if(typeof testSaveDraft==='function')testSaveDraft(current.id,current.code);}else if(!current.isReview){state.drafts[current.id]=current.code;save();}passedCode=null;$('#completion-message').textContent='Code changed. Run the checks again before completing.';syncLines();}if(e.target.id==='explanation'&&!current.isReview){state.explanations[current.id]=e.target.value;save();}if(e.target.id==='scratch'){state.scratch=e.target.value;save();}if(e.target.id==='session-note'){state.notes[current.id]=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.dataset.project){state.projectChecks[e.target.dataset.project]=e.target.checked;save();}if(e.target.id==='timer-minutes'){state.timerMinutes=Number(e.target.value);save();toast('Timer preference saved.');}if(e.target.id==='import-file')importBackup(e.target.files[0]);});
document.addEventListener('keydown',e=>{if(e.target.id==='editor'){if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('    ',e.target.selectionStart,e.target.selectionEnd,'end');e.target.dispatchEvent(new Event('input',{bubbles:true}));}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}}});
document.addEventListener('click',e=>{const r=e.target.closest('[data-rating]');if(r){rating=Number(r.dataset.rating);document.querySelectorAll('[data-rating]').forEach(b=>b.classList.toggle('selected',b===r));}const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='run')run();if(action==='stop')stopRun('Stopped. You can edit your code and try again.');if(action==='hint'){current.hints=Math.min(2,current.hints+1);markAssisted();renderHints();}if(action==='refresher'){$('#refresher').hidden=false;markAssisted();el.hidden=true;}if(action==='solution'){if(!confirm('Reveal the reference solution? This attempt will count as guided practice. Your draft will be replaced; download it first if you want to keep it.'))return;markAssisted();$('#editor').value=lessons[current.id-1].solution;$('#editor').dispatchEvent(new Event('input',{bubbles:true}));toast('Trace each line. Revisit from scratch later to test recall.');}if(action==='reset-code'){if(!confirm('Replace the code in this editor with the starter? Your notes will be kept.'))return;$('#editor').value=current.starter;$('#editor').dispatchEvent(new Event('input',{bubbles:true}));}if(action==='download-code')download(current.file||current.name+'.py',$('#editor').value);if(action==='complete')complete();if(action==='timer'){if(timerRunning)pauseTimer();else{timerRunning=true;lastTick=Date.now();$('#timer-toggle').textContent='Pause';clock=setInterval(()=>{const now=Date.now();elapsed+=(now-lastTick)/1000;lastTick=now;tick();},1000);}}if(action==='timer-reset'){pauseTimer();elapsed=0;tick();$('#timer-toggle').textContent='Start focus timer';}if(action==='export')exportBackup();if(action==='import')$('#import-file').click();if(action==='export-notes')download('forge-notebook.md','# My Forge notebook\n\n'+state.scratch+'\n\n'+lessons.filter(l=>state.notes[l.id]||state.explanations[l.id]).map(l=>'## '+l.title+'\n\n'+(state.explanations[l.id]||'')+'\n\n'+(state.notes[l.id]||'')).join('\n\n'));if(action==='project-brief'){const p=projects[Number(el.dataset.projectId)];download(p.title.toLowerCase().replaceAll(' ','-')+'.md',`# ${p.title}\n\n${p.desc}\n\n## Definition of done\n${p.checks.map(c=>'- [ ] '+c).join('\n')}\n\n## Build in VS Code\n1. Create a project folder and a README.\n2. Download your challenge function from Forge as core.py.\n3. Create main.py for the CLI and test_core.py for tests.\n4. Keep file access and input() in main.py; keep core.py pure.\n5. Write an ordinary case, an empty case, and a boundary case using unittest.\n6. Run: python -m unittest\n7. Run: python main.py\n8. Document setup, sample input, expected output, and limitations.\n\n## Next extension\n${lessons[p.id-1].extension}\n`);}});
async function importBackup(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup is too large.');const obj=JSON.parse(await file.text());if(obj.version!==1)throw Error('This is not a supported Forge backup.');const clean=emptyState(),stringMaps=['drafts','notes','explanations'];for(const key of stringMaps){if(!obj[key]||typeof obj[key]!=='object'||Array.isArray(obj[key]))throw Error('Invalid '+key);for(const [id,value] of Object.entries(obj[key])){if(!validLessonKey(id)||typeof value!=='string'||value.length>200000)throw Error('Invalid '+key+' entry');clean[key][id]=value;}}for(const key of ['completed','reviews','assisted','hints','ratings','projectChecks']){if(!obj[key]||typeof obj[key]!=='object'||Array.isArray(obj[key]))throw Error('Invalid '+key);for(const [id,v] of Object.entries(obj[key])){if(key==='projectChecks'){if(!/^[0-3]-[0-2]$/.test(id)||typeof v!=='boolean')throw Error('Invalid project checkpoint');}else{if(!validLessonKey(id))throw Error('Invalid lesson ID');if(key==='completed'&&(!v||!Number.isFinite(v.at)||!Number.isFinite(v.due)||typeof v.assisted!=='boolean'))throw Error('Invalid completion');if(key==='reviews'&&(!v||!Number.isFinite(v.due)||!Number.isInteger(v.stage)||v.stage<0||v.stage>3))throw Error('Invalid review');if(key==='assisted'&&typeof v!=='boolean')throw Error('Invalid assistance');if(key==='hints'&&(!Number.isInteger(v)||v<0||v>2))throw Error('Invalid hint count');if(key==='ratings'&&![1,2,3].includes(v))throw Error('Invalid rating');}clean[key][id]=v;}}if(!Array.isArray(obj.events)||obj.events.some(e=>!e||!Number.isInteger(e.id)||e.id<1||e.id>lessons.length||!Number.isFinite(e.at)))throw Error('Invalid session history');clean.events=obj.events.map(e=>({id:e.id,at:e.at,review:!!e.review,assisted:!!e.assisted}));for(const key of ['labChecks','labNotes','evidence']){const map=obj[key]||{};if(typeof map!=='object'||Array.isArray(map))throw Error('Invalid '+key);for(const [id,value] of Object.entries(map)){const allowed=key==='labChecks'?/^([1-9]|1[0-9]|2[0-4])-([0-9]+)$/.test(id):key==='labNotes'?/^(0?[1-9]|1[0-9]|2[0-4])$/.test(id):/^skill-[0-9]+$/.test(id);if(!allowed||(key==='labChecks'?typeof value!=='boolean':typeof value!=='string'))throw Error('Invalid '+key+' entry');clean[key][id]=value;}}if(typeof obj.scratch!=='string')throw Error('Invalid notebook');clean.scratch=obj.scratch;clean.timerMinutes=[25,45,60].includes(obj.timerMinutes)?obj.timerMinutes:45;if(typeof sanitizeGame==='function')clean.game=sanitizeGame(obj.game);if(!confirm('Replace this browser’s current Forge progress with this backup? Forge keeps a snapshot of your current progress first, so you can undo this from settings.'))return;takeSnapshot(true);saveBlocked=false;progressUnreadable=false;clearNotice('recovery');clearNotice('stale');state=clean;save();route();toast('Backup restored. Your workspace is ready.');}catch(error){toast('Could not import: '+error.message);$('#import-file').value='';}}
window.addEventListener('hashchange',route);
lastSnapshotAt=readSnapshots().reduce((latest,s)=>Math.max(latest,s.at),0);showRecoveryNotice();signalTabs('ping');
Promise.all([fetch('curriculum.json?v='+FORGE_VERSION),fetch('handbook.json?v='+FORGE_VERSION)].map(async pending=>{const response=await pending;if(!response.ok)throw Error('Course content unavailable');return response.json();})).then(([data,book])=>{curriculum=data;handbook=book;lessons=data.lessons;weeks=data.weeks;takeSnapshot();route();checkBackupReminder();}).catch(e=>{$('#main').innerHTML='<div class="card empty-state"><h1>Let’s reconnect.</h1><p>The learning path could not load. Refresh the page to try again.</p><button class="btn" onclick="location.reload()">Try again</button></div>';});

/* Course edition 2: teaching, local practice, and evidence beyond function checks. */
function validLessonKey(id){return /^\d+$/.test(id)&&lessons.some(l=>l.id===Number(id));}
function sourceLinks(keys){return keys.map(key=>{const s=handbook.sources[key];return `<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(s.title)} <span aria-hidden="true">↗︎</span></strong><small>${esc(s.purpose)}</small></a>`;}).join('');}
function courseToolbar(){return `<div class="course-toolbar"><a href="#guide">How to use Forge</a><a href="#setup">Lab setup</a><details><summary>More</summary><a href="#quests">Quest book</a><a href="#practice">Optional practice library</a><a href="#resources">Sources & coverage</a><a href="#readiness">Readiness evidence</a></details></div>`;}
function renderHome(){if(typeof questMigrate==='function')questMigrate();const next=learningNext(),u=handbook.units[next.week-1],due=dueLessons().length;return `${header('One step at a time.','Learn an idea. Practice it. Build something of your own.')}<div class="flow-home"><section class="card next-step"><span class="eyebrow">YOUR NEXT STEP · WEEK ${next.week}</span><h2>${esc(next.title)}</h2><p>${esc(next.description)}</p><a class="btn primary" href="${next.href}">${next.label} →</a><p class="muted">${progressForWeek(next.week)} of 4 browser sessions saved · ${courseLabDone(next.week)?'local lab recorded':'local lab follows the practice'}</p></section><ol class="learning-sequence"><li><b>1</b><div><strong>Learn</strong><p>Read the explanation. Trace a worked example.</p></div></li><li><b>2</b><div><strong>Practice</strong><p>Write your own code. Use the checks to debug it.</p></div></li><li><b>3</b><div><strong>Build independently</strong><p>Make a complete program in the weekly local lab.</p></div></li></ol><section class="card home-support"><h2>New to programming?</h2><p>Start in your browser. Nothing to install for the lessons. When you reach the local lab, the setup guide walks you through Python, VS Code, and your first test run.</p><a href="#guide">How your first week works →</a><a href="#setup/${next.week}">Set up your computer for the lab →</a></section>${due?`<p class="review-reminder"><a href="#review">${due} saved skill${due===1?' is':'s are'} ready to revisit.</a> A short review can be your warm-up.</p>`:''}<p class="muted">Aim for four 45–60 minute sessions a week. Setup and projects can take extra sessions. Move on when you understand the work.</p></div>`;}
function renderPath(){const focused=Number(location.hash.split('week-')[1])||learningNext().week;return `${header('Your learning path','Work through each week: learn, practice, then build the local lab.')}${courseToolbar()}<p class="path-pace">24 weeks of material, at your pace. The four browser sessions are practice; the local lab is where you put them together.</p>${weeks.map((w,i)=>{const u=handbook.units[i],week=i+1;return `<details class="card week-card" id="week-${week}" ${week===focused?'open':''}><summary><span class="path-number">${String(week).padStart(2,'0')}</span><div><h3>${esc(w.title)}</h3><p>${esc(w.subtitle)}</p></div><span class="week-count">${progressForWeek(week)} / 4 · ${courseLabDone(week)?'lab recorded':'lab to build'}</span></summary><div class="unit-preview"><a class="btn light" href="#unit/${week}">1. Read the lesson →</a></div><div class="lesson-grid">${lessons.filter(l=>isCore(l)&&l.week===week).map(l=>`<a class="lesson-link" href="#lesson/${l.id}"><span class="lesson-state">${state.completed[l.id]?'✓':'○'}</span><div>${l.session}. ${esc(l.title)}<small>${l.checkpoint?'Apply the ideas':'Practice'}${state.completed[l.id]?' · '+(state.completed[l.id].assisted?'Guided':'Independent'):''}</small></div></a>`).join('')}</div><div class="week-lab-summary"><strong>3. Build: ${esc(u.lab.title)}</strong><p>Use the ideas in a complete local program.</p><a class="btn light" href="#lab/${week}">Open independent lab →</a></div></details>`;}).join('')}`;}
function courseLessonBanner(l,isReview){return `<div class="lesson-course-banner"><div><strong>${isReview?'Fresh recall attempt':'Week '+l.week+' · handbook and local practice'}</strong><p>${isReview?'Keep the handbook closed for this attempt; revealing teaching material counts as guidance.':'New to the concept? Read the handbook first, then return to this challenge.'}</p></div>${isReview?'':`<a class="btn light small" href="#unit/${l.week}">Open handbook →</a>`}</div>`;}
function workedBlock(u){return `<section class="worked-example"><span class="eyebrow">A SEPARATE WORKED EXAMPLE</span><pre>${esc(u.worked.code)}</pre><div class="button-row"><button class="btn light small" data-course-action="example" data-week="${u.week}">Run this example ▶︎</button><span class="muted">Predict its output before running.</span></div><pre class="example-output" id="example-output" aria-live="polite">Output appears here.</pre><details><summary>Trace the example and see expected output</summary><pre>${esc(u.worked.output)}</pre><ol>${u.worked.trace.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details></section>`;}
function paras(text){return String(text||'').split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('');}
function teachingSection(s,id,number){return `<section class="plain teaching-topic" id="${id}" tabindex="-1"><span class="learn-kicker">TOPIC ${number}</span><h3>${esc(s.title)}</h3>${paras(s.text)}${s.code?`<p class="teaching-code-label">${s.shell?'Local example · follow the file and terminal instructions above':'Python example · read it, then predict the output'}</p><pre>${esc(s.code)}</pre>`:''}${s.output!==undefined?`<div class="teaching-output"><p class="teaching-code-label">Expected output</p><pre>${esc(s.output||'(No printed output.)')}</pre></div>`:''}${s.walk?.length?`<div class="teaching-walk"><h4>Follow what happens</h4><ol>${s.walk.map(line=>`<li>${esc(line)}</li>`).join('')}</ol></div>`:''}${s.check?`<div class="teaching-check"><strong>Pause and explain</strong>${paras(s.check)}</div>`:''}</section>`;}
function teachingSections(u){const sections=u.plain||[];return `<div class="teaching-sections"><p class="teaching-reading-note">Read these topics in order. Each example is separate from your practice task. Pause at the questions; a chapter can take several sessions.</p><details class="teaching-contents"><summary>In this chapter · ${sections.length} topics · open to jump to one</summary><ol>${sections.map((s,i)=>`<li><button type="button" data-teaching-target="topic-${u.week}-${i+1}">${esc(s.title)}</button></li>`).join('')}</ol></details><div class="plain-sections">${sections.map((s,i)=>teachingSection(s,`topic-${u.week}-${i+1}`,i+1)).join('')}</div><details class="teaching-reference"><summary>After reading: quick reference${u.watch?' & optional video':''}</summary>${u.watch?`<p><a href="${esc(u.watch.url)}" target="_blank" rel="noopener noreferrer">${esc(u.watch.label)}</a></p><p>The video is optional. Use the step-by-step written topics above before this compact reference.</p>`:''}${u.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></section>`).join('')}</details></div>`;}
function lessonTabs(practiceFirst){const tab=(id,n,label,on)=>`<button role="tab" data-ltab="${id}" class="${on?'active':''}" aria-selected="${on}"><b>${n}</b>${label}</button>`;return `<div class="lesson-tabs" role="tablist" aria-label="Lesson steps">${tab('learn',1,'Learn the idea',!practiceFirst)}<span aria-hidden="true">→</span>${tab('practice',2,'Write & test',practiceFirst)}</div>`;}function weekMinutes(u){const words=(u.plain||[]).reduce((n,s)=>n+String(s.text||'').split(/\s+/).length+String(s.code||'').split(/\s+/).length+String(s.output||'').split(/\s+/).length+String((s.walk||[]).join(' ')).split(/\s+/).length+String(s.check||'').split(/\s+/).length,0)+u.sections.reduce((n,s)=>n+String(s.text).split(/\s+/).length,0);return Math.max(2,Math.round(words/170));}function lessonLearnView(l,practiceFirst){const u=l.noWeek?null:handbook.units[l.week-1];const teach=l.teach?l.teach.map(s=>`<section class="plain"><h3>${esc(s.title)}</h3>${paras(s.text)}${s.code?`<pre>${esc(s.code)}</pre>`:''}</section>`).join(''):'';const firstOfWeek=!l.track&&l.session===1;const week=u?`<details class="card learn-week" ${firstOfWeek?'open':''}><summary><span class="learn-kicker">${firstOfWeek?'This week’s lesson':'Need a refresher?'}</span><strong>Week ${l.week}: ${esc(u.title)}</strong><small>${firstOfWeek?'Read these topics in order before the challenge. Trace the examples and pause at the questions.':'The full week '+l.week+' lesson, if today’s idea doesn’t click.'} About ${weekMinutes(u)} min.</small></summary><div class="learn-week-body">${teachingSections(u)}<p class="learn-note">The <a href="#unit/${l.week}">week ${l.week} handbook</a> also has a runnable worked example, common mistakes, and the local lab.</p></div></details>`:'';return `<div class="learn-view" ${practiceFirst?'hidden':''}>${!l.track?week:''}<section class="card learn-card"><span class="learn-kicker">Today’s idea</span><p class="learn-lead">${esc(l.concept)}</p>${l.example?`<pre>${esc(l.example)}</pre>`:''}${teach?`<div class="plain-sections">${teach}</div>`:''}</section>${l.track?week:''}<div class="learn-next"><div><strong>Ready to try it?</strong><p>Next you’ll write <code>${esc(l.program?'a whole program':l.name)}</code> on your own. You can come back here any time.</p></div><button class="btn" data-ltab="practice">Open 2. Write & test →</button></div></div>`;}
function renderUnit(number){const u=handbook.units.find(x=>x.week===number);if(!u)return renderPath();const first=lessons.find(l=>!l.track&&l.week===number&&!state.completed[l.id])||lessons.find(l=>!l.track&&l.week===number);return `<a class="back" href="#path/week-${number}">← Learning path</a>${header(`Week ${number}: ${esc(u.title)}`,'Learn the idea, trace an example, then try it yourself.')}<div class="reading-page"><article class="card handbook-article"><h2>What you will learn</h2><ul>${u.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p class="prerequisite"><strong>Before you start:</strong> ${esc(u.prerequisites)}.</p>${teachingSections(u)}${workedBlock(u)}<section class="mistake-panel"><h3>Common mistakes</h3><ul>${u.mistakes.map(m=>`<li>${esc(m)}</li>`).join('')}</ul></section><section><h3>Check your understanding</h3><ol>${u.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p>Explain these in your own words. If an answer feels unclear, trace the example again with a different input.</p><a class="btn" href="#lesson/${first.id}">Try the practice →</a></section><details class="unit-sources"><summary>Sources & further reading</summary>${sourceLinks(u.sources)}</details></article><section class="card home-support"><h2>After the practice: your local lab</h2><p>${esc(u.lab.title)}. Build it on your computer after the week's four browser sessions.</p><a href="#lab/${number}">Open the lab brief →</a></section></div>`;}
function renderProjects(){const next=learningNext();return `${header('Labs & projects','Build complete programs on your computer. Keep the code, tests, and examples.')}<div class="setup-callout"><div><strong>First local lab?</strong><p>Follow the setup guide from installing Python to running your first tests.</p></div><a class="btn light" href="#setup/${next.week}">Start lab setup →</a></div><div class="section-title"><h2>Your next lab</h2></div><section class="card next-step"><span class="badge">WEEK ${next.week}</span><h2>${esc(handbook.units[next.week-1].lab.title)}</h2><p>Finish the week's browser practice, then build from the lab brief. Use documentation when needed; attempt the program without a generated solution.</p><a class="btn" href="#lab/${next.week}">Open lab brief →</a></section><details class="lab-library"><summary>Browse all 24 labs & projects</summary><div class="lab-catalog">${handbook.units.map(u=>`<a class="card lab-tile" href="#lab/${u.week}"><span class="badge">WEEK ${u.week}${courseLabDone(u.week)?' · RECORDED':''}</span><h3>${esc(u.lab.title)}</h3><p>${esc(u.goals[0])}</p><small>${u.lab.acceptance.filter((_,j)=>state.labChecks[`${u.week}-${j}`]).length} / ${u.lab.acceptance.length} criteria checked</small></a>`).join('')}</div></details><p><a href="#readiness">Review your evidence of independent work →</a></p>`;}
const readinessSkills=[
 ['Python fundamentals','Implement a small unfamiliar function from a written spec; explain values, control flow, collections, functions, mutation, and errors.','Weeks 1–5 and 12',12],
 ['Independent problem solving','Clarify a changed requirement, choose a data structure, solve examples, and explain time/space costs.','Weeks 8–9, 19, and 24',24],
 ['Debugging and tests','Reproduce a bug, add a test that fails on the buggy version, fix it, and run the suite.','Weeks 5, 14, and 22',14],
 ['Developer workflow','Create a clean environment, inspect diffs, make a focused branch/commit, and prepare a reviewable PR.','Start Here and weeks 13, 22–23',13],
 ['Files and automation','Build a CLI that validates data, previews changes, reports failures, and behaves predictably on reruns.','Weeks 6–7, 15, and 21',21],
 ['SQL','Write filtered queries, a grouped report, and a join; bind values and verify a transaction rollback.','Week 16',16],
 ['HTTP and service boundaries','Handle status/errors/timeouts and pagination; expose tested rules through a small local API.','Weeks 17 and 20',20],
 ['Maintainability','Read an existing feature path, preserve a contract, inject an I/O dependency, and document a change.','Weeks 10, 18, and 22',22],
 ['A shipped project','Demonstrate a complete workflow with sample data, tests, clean setup instructions, and an honest limitation.','Weeks 11 and 23',23],
 ['Interview and handoff communication','Explain a project tradeoff and bug fix, complete a small take-home change, and identify what remains uncertain.','Week 24',24]
];
function renderReadiness(){const recorded=readinessSkills.filter((_,i)=>(state.evidence[`skill-${i}`]||'').trim().length>=40).length;return `${header('Show yourself what you can do','Use working examples and independent attempts to decide what to practice next.')}${courseToolbar()}<div class="path-intro"><strong>${recorded} / ${readinessSkills.length}</strong><p>Areas with an evidence note of at least 40 characters. This counts recorded reflection, not verified mastery. Include a repository link, run command, output, test result, and help used. Revise the note when a new attempt exposes a gap.</p></div><div class="readiness-grid">${readinessSkills.map(([title,desc,weeks,week],i)=>`<section class="card readiness-card"><span class="badge">${esc(weeks)}</span><h2>${esc(title)}</h2><p>${esc(desc)}</p><label for="evidence-${i}">My evidence, help used, and next gap</label><textarea id="evidence-${i}" class="form-input" data-evidence="skill-${i}" rows="5" placeholder="I independently built/fixed… I verified it by… I used help with… Next I need to practice…">${esc(state.evidence[`skill-${i}`]||'')}</textarea><a class="btn light small" href="#unit/${week}">Revisit this practice →</a></section>`).join('')}</div><section class="card handbook-article" style="margin-top:20px"><h2>Choose your next specialization</h2><p>This path develops Python, automation, backend basics, and shared engineering habits. A particular role may need additional skills. Use a real job description to decide what to add: frontend roles need HTML/CSS/JavaScript and accessibility; data roles may need deeper SQL, statistics, and pandas; game programming may need C#/C++, engine workflows, and real-time systems. Infrastructure roles may need Linux, networking, and cloud operations. Build the fundamentals here, then add one relevant track rather than trying to learn every stack at once.</p><p>Start applying and discussing your projects while practicing. Use interview feedback and independent work to adjust this rubric; you do not need to feel finished learning before exploring entry-level roles.</p></section>`;}
function renderResources(){const groups=[['Beginner explanations',['w3','w3vars','w3func','cs50']],['Python language and standard library',['python','values','flow','collections','modules','files','errors','classes','regex','dates','paths','csv','containers','heap','dataclass','annotations']],['Developer tools and testing',['vscode','venv','mit','git','github','pytest','unittest','args','logging','ci']],['Databases and services',['w3sql','sql','http','requests','api']]];return `${header('Sources and curriculum coverage','A researched map with original lessons and direct references.')}${courseToolbar()}<section class="card handbook-article"><h2>How the content is used</h2><p>Forge combines a beginner-friendly sequence informed by W3Schools and CS50P, Python behavior checked against the official documentation, and practical tools supported by their maintainers’ documentation. The teaching, game examples, challenges, and lab specifications are original. External readings are optional explanations or references rather than copied course chapters.</p><p>Reviewed ${esc(handbook.edition)}. The bundled browser interpreter is Python 3.12; examples target compatible Python 3 behavior. External documentation can move to a newer release. Use the documentation version selector if a feature differs from your local interpreter. Newer optional features are not required by these exercises.</p><h3>Coverage and boundaries</h3><p>Included: values/types, operators, conditions, loops, strings, collections, functions/scope, mutation, modules, exceptions, files, JSON/CSV, basic OOP, iterators, regex, dates, testing, environments, Git, SQL, HTTP, small services, logging, core algorithm patterns, maintenance, and project delivery.</p><p>Not a complete computer-science degree or every role’s stack. Advanced metaprogramming, distributed systems, advanced async/concurrency, deep framework internals, and production-scale deployment are future specializations. The purpose is reliable beginner-to-entry-level Python practice and evidence of independent work.</p></section>${groups.map(([title,keys])=>`<section class="card handbook-article source-group"><h2>${title}</h2><div class="source-grid">${sourceLinks(keys)}</div></section>`).join('')}`;}
function renderSetup(number=1){const week=validWeek(number),setup=handbook.setup;if(!setup)return renderGuide();return `${header(setup.title,setup.intro)}<div class="reading-page"><a class="back" href="#lab/${week}">← Week ${week} lab</a>${platformPicker()}<div class="setup-contents"><strong>Follow in order</strong><ol>${setup.sections.map((x,i)=>`<li><a href="#setup/${week}" data-setup-jump="setup-step-${i+1}">${esc(x.title)}</a></li>`).join('')}</ol></div>${setup.sections.map((x,i)=>`<section class="card learn-card setup-step" id="setup-step-${i+1}"><span class="learn-kicker">STEP ${i+1} OF ${setup.sections.length}</span><h2>${esc(x.title)}</h2>${paras(x.text)}${(x.links||[]).map(l=>`<p><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a></p>`).join('')}${x.download?`<a class="btn" href="labs/week-${String(week).padStart(2,'0')}.zip" download>Download week ${week} starter kit ↓</a>`:''}${x.code?`<p class="command-label">${esc(x.codeLabel||"In the file hello.py:")}</p><pre>${esc(x.code)}</pre>`:''}${x[setupPlatform]?`<p class="command-label">In the terminal · ${platformName()}:</p><pre>${esc(x[setupPlatform])}</pre>`:''}${x.after?paras(x.after):''}</section>`).join('')}<section class="card learn-card"><h2>If something goes wrong</h2>${setup.problems.map(x=>`<details class="setup-problem"><summary>${esc(x.title)}</summary>${paras(x.text)}</details>`).join('')}<p>Official references: <a href="https://code.visualstudio.com/docs/python/python-tutorial" target="_blank" rel="noopener noreferrer">VS Code Python setup</a> · <a href="https://docs.python.org/3/library/venv.html" target="_blank" rel="noopener noreferrer">Python environments</a>.</p></section><div class="learn-next"><div><strong>Your tools are ready.</strong><p>Return to this week's brief and build one small piece.</p></div><a class="btn" href="#lab/${week}">Open week ${week} lab →</a></div></div>`;}
function renderGuide(){return `${header('Start here. You can begin today.','No installation needed for your first browser lesson.')}<div class="reading-page"><article class="card handbook-article"><h2>Your first week</h2><ol class="guide-steps"><li><strong>Learn one idea.</strong><p>Open the first lesson and read its Learn tab. Read the code slowly and predict what it does. The written teaching is enough to start; videos are optional.</p></li><li><strong>Practice in the browser.</strong><p>Switch to Practice. Read the task, work a small example on paper, then edit the starter code. Run checks and inspect one failure at a time. A failed check gives you something specific to investigate.</p></li><li><strong>Explain and revisit.</strong><p>After passing the checks, explain your approach and a boundary case. Record help honestly. Reviews let you try again later from a fresh editor.</p></li><li><strong>Build a local program.</strong><p>After the four practice sessions, open the week's lab. The setup guide walks you through the tools. Follow the brief, write your own tests, and demonstrate that your program meets the acceptance criteria.</p></li></ol><a class="btn" href="#lesson/1">Begin the first lesson →</a><h2>A pace you can keep</h2><p>Aim for four 45–60 minute sessions a week. Start with a short review, learn and practice, then explain what you did. A lab or first-time setup may need extra sessions. The week numbers organize the material; they are not deadlines.</p><h2>When you get stuck</h2><p>Write the input, what you expected, and what actually happened. Trace the smallest failing example. Use the hint ladder for a nudge after trying. Looking up syntax is part of programming. If you use a complete answer, record it as help and try again later without copying.</p><h2>What to focus on</h2><p>Follow Learn → Practice → Local lab. The quest book is your main course. Optional practice tracks are separate. You do not have to complete every side quest to continue the course.</p><h2>Keep your work</h2><p>Forge saves browser progress on this browser and address. Export a backup in Settings regularly. Local lab files live separately on your computer: back those up too.</p></article><section class="card home-support"><h2>Ready for your first lab?</h2><p>The setup guide explains Python, VS Code, folders, terminal commands, and expected test failures.</p><a href="#setup/1">Set up the week 1 lab →</a></section><details class="card handbook-article"><summary>A few words you will see</summary>${[['Value','A piece of data, such as a number or text.'],['Variable','A name that refers to a value.'],['Function','A named piece of code you can call with inputs.'],['Return','Pass a result back to the code that called a function.'],['Print','Display text for a person to read.'],['Test','Run code with a known input and check what happens.'],['Terminal','A panel where you type commands to run programs.'],['Interpreter','The program that runs your Python code.'],['Environment','A project folder containing its Python interpreter and installed tools.']].map(([term,meaning])=>`<h3>${term}</h3><p>${meaning}</p>`).join('')}</details></div>`;}

async function runWorkedExample(week){const u=handbook.units.find(x=>x.week===week),button=document.querySelector('[data-course-action="example"]');if(!u||!button||button.disabled)return;stopRun();button.disabled=true;$('#example-output').textContent='Loading Python and running the example…';worker=new Worker('runner.js?v='+FORGE_VERSION);runTimeout=setTimeout(()=>{stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent='Python took too long. Try again after checking your connection.';},90000);worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(runTimeout);runTimeout=setTimeout(()=>{stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent='Stopped after 8 seconds.';},8000);}else if(data.type==='result'||data.type==='error'){stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent=data.type==='error'?data.message:(data.data.error||data.data.stdout||'The example produced no printed output.');}};worker.onerror=()=>{stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent='Could not run Python. Try again.';};worker.postMessage({code:u.worked.code,name:'',cases:[],packages:week===16?['sqlite3']:[]});}
document.addEventListener('click',e=>{const element=e.target.closest('[data-course-action]');if(element?.dataset.courseAction==='example')runWorkedExample(Number(element.dataset.week));});
document.addEventListener('change',e=>{const key=e.target.dataset.lab;if(key){state.labChecks[key]=e.target.checked;save();}});
document.addEventListener('click',e=>{const dismiss=e.target.closest('[data-notice-dismiss]');if(dismiss)dismissNotice(dismiss.dataset.noticeDismiss);const el=e.target.closest('[data-safety]');if(!el)return;const action=el.dataset.safety,key=el.dataset.recoveryKey;if(action==='reload')location.reload();if(action==='restore-snapshot')restoreSnapshot(Number(el.dataset.snapshot));if(action==='download-recovery')download('forge-progress-recovery-'+(key.split('-').pop())+'.json',localStorage.getItem(key)||'','application/json');if(action==='delete-recovery'&&confirm('Delete this recovery copy? This cannot be undone.')){localStorage.removeItem(key);route();}});
document.addEventListener('input',e=>{if(e.target.dataset.labNotes){state.labNotes[e.target.dataset.labNotes]=e.target.value;save();}if(e.target.dataset.evidence){state.evidence[e.target.dataset.evidence]=e.target.value;save();}});
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-ltab]');if(!t)return;const learn=t.dataset.ltab==='learn',lv=$('.learn-view'),pv=$('.practice-view');if(!lv||!pv)return;lv.hidden=!learn;pv.hidden=learn;document.querySelectorAll('.lesson-tabs [data-ltab]').forEach(x=>{const on=(x.dataset.ltab==='learn')===learn;x.classList.toggle('active',on);x.setAttribute('aria-selected',String(on));});window.scrollTo(0,0);if(!learn){syncLines();$('#editor')?.focus();}});

/* A direct learning flow; saved lesson and lab records remain backward compatible. */
let setupPlatform='windows';
function validWeek(number){return Number.isInteger(number)&&number>=1&&number<=24?number:1;}
function platformName(){return {windows:'Windows (PowerShell)',mac:'macOS',linux:'Linux'}[setupPlatform];}
function platformPicker(){return `<div class="platform-picker" role="group" aria-label="Your computer"><span>Show commands for</span>${[['windows','Windows'],['mac','macOS'],['linux','Linux']].map(([key,label])=>`<button class="btn light small" data-platform="${key}" aria-pressed="${key===setupPlatform}">${label}</button>`).join('')}</div>`;}
function courseLabDone(week){if(typeof labDone==='function')return labDone(week);const u=handbook.units[week-1];return !!u&&u.lab.acceptance.every((_,j)=>state.labChecks[`${week}-${j}`])&&(state.labNotes[week]||'').trim().length>=80;}
function learningNext(){for(const u of handbook.units){const l=lessons.find(l=>!l.track&&l.week===u.week&&!state.completed[l.id]);if(l)return {week:u.week,title:l.title,description:u.week===1&&l.session===1?'Start with the explanation, then write your first function in the browser. No setup needed.':`Continue ${u.title.toLowerCase()}. Read the idea, write your code, and explain what you learned.`,href:'#lesson/'+l.id,label:state.drafts[l.id]?'Resume lesson':'Open lesson'};if(!courseLabDone(u.week))return {week:u.week,title:u.lab.title,description:'You have finished the browser practice for this week. Now use the ideas to build a complete program on your computer.',href:'#lab/'+u.week,label:'Start local lab'};}return {week:24,title:'Look at what you can build',description:'Your core sessions and lab records are complete. Review the evidence, revisit a weak area, or try an unfamiliar project.',href:'#readiness',label:'Review your evidence'};}
function labContinuation(week){const done=courseLabDone(week);return `<p role="status">${done?'Lab recorded. Keep your program files and test results as evidence.':'Check each criterion after trying it, then write at least 80 characters about what you ran, what happened, and help used. These are your own records; Forge does not inspect local files.'}</p>${done?`<a class="btn" href="${week<24?'#lesson/'+(week*4+1):'#readiness'}">${week<24?'Continue to week '+(week+1):'Review your evidence'} →</a>`:''}`;}
function updateLabContinuation(week){const el=$('#lab-continuation');if(el)el.innerHTML=labContinuation(week);}
function renderLab(number){const week=validWeek(number),u=handbook.units[week-1],ready=progressForWeek(week)===4;return `<a class="back" href="#projects">← Labs & projects</a>${header(`Week ${week}: ${esc(u.lab.title)}`,'Build a complete program from a brief. Work in small steps and verify your own results.')}<div class="reading-page">${!ready?`<p class="course-notice">Before building, finish the week's four practice sessions (${progressForWeek(week)}/4 saved). <a href="#path/week-${week}">Open this week's learning path →</a></p>`:''}<section class="card home-support"><h2>1. Get your files ready</h2><p>First time? Follow the setup guide. Already set up? Extract this week's kit into its own folder, open it in VS Code, and create its .venv as described in the kit's README.</p><div class="button-row"><a class="btn" href="#setup/${week}">Step-by-step setup →</a><a class="btn light" href="labs/week-${String(week).padStart(2,'0')}.zip" download>Download week ${week} kit ↓</a></div><p>The kit supplies an unfinished checkpoint function and tests. The full program below is yours to build. Read the requirements before writing code.</p></section><article class="card handbook-article"><h2>2. Plan, then build</h2><p>Write an example input and expected output in your README. Describe a simple approach before coding. Use documentation for syntax; try the design and implementation yourself.</p><ol class="lab-build-steps">${u.lab.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><h3>If you get stuck</h3><p>Reduce the problem to one small input. Write the expected and actual result, then trace the relevant lines. Revisit <a href="#unit/${week}">this week's teaching</a> for the concept. If you need help, ask for a hint or a review of your attempt, then record what help you used.</p><h2>3. Test the complete program</h2><p>Run the supplied tests, then add your own examples in test_core.py. Try an ordinary input and a relevant boundary or invalid input. Run main.py as well: passing core tests alone does not demonstrate the full workflow.</p><details class="lab-commands"><summary>Show run commands</summary>${platformPicker()}<pre>${esc(setupPlatform==='windows'?'.\\.venv\\Scripts\\python.exe -m unittest -v\n.\\.venv\\Scripts\\python.exe main.py':'./.venv/bin/python -m unittest -v\n./.venv/bin/python main.py')}</pre><p>Run these from the week folder after creating .venv. Save your files first.</p></details><h3>Try each acceptance criterion</h3><div class="checklist">${u.lab.acceptance.map((criterion,j)=>`<label><input type="checkbox" data-lab="${week}-${j}" ${state.labChecks[`${week}-${j}`]?'checked':''}>${esc(criterion)}</label>`).join('')}</div><h2>4. Keep evidence of your work</h2><ul>${u.lab.deliverables.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><label for="lab-evidence">What did you run, what happened, and what did you learn?</label><textarea class="form-input" id="lab-evidence" data-lab-notes="${week}" rows="6" placeholder="Command and example I tried… Expected / actual result… One bug I fixed… Help used… Anything unfinished…">${esc(state.labNotes[week]||'')}</textarea><small>Your note and checkboxes save automatically in this browser. Back up your local files separately.</small><div id="lab-continuation">${labContinuation(week)}</div></article></div>`;}
document.addEventListener('click',e=>{const jump=e.target.closest('[data-setup-jump]');if(jump){e.preventDefault();document.getElementById(jump.dataset.setupJump)?.scrollIntoView({behavior:'smooth',block:'start'});return;}const button=e.target.closest('[data-platform]');if(button&&['windows','mac','linux'].includes(button.dataset.platform)){setupPlatform=button.dataset.platform;const scroll=window.scrollY,commands=document.querySelector('.lab-commands')?.open;route();if(commands)document.querySelector('.lab-commands').open=true;window.scrollTo(0,scroll);document.querySelector(`[data-platform="${setupPlatform}"]`)?.focus();}});
document.addEventListener('change',e=>{if(e.target.dataset.lab)updateLabContinuation(Number(e.target.dataset.lab.split('-')[0]));});
document.addEventListener('input',e=>{if(e.target.dataset.labNotes)updateLabContinuation(Number(e.target.dataset.labNotes));});

function appearanceSettings(){const preference=typeof ForgeAppearance==='undefined'?'system':ForgeAppearance.getPreference();return `<section class="card settings-card"><h3>Comfortable for the long run</h3><p>Choose a soft light palette or a quiet dark workspace. System follows your device. Your choice is remembered in this browser.</p><div class="theme-options" role="group" aria-label="Color theme">${[['system','System'],['light','Light'],['dark','Dark']].map(([value,label])=>`<button type="button" data-theme-choice="${value}" aria-pressed="${preference===value}">${label}</button>`).join('')}</div><p>You can also switch between light and dark with the theme button at the top of any page.</p></section>`;}

// Topic jumps keep the chapter route and move keyboard focus with the reader.
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-teaching-target]');if(!button)return;
  const topic=document.getElementById(button.dataset.teachingTarget);if(!topic)return;
  topic.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
  topic.focus({preventScroll:true});
});
